// ── GATE 1: API Key / PIN auth (SHA-256, timing-safe, brute-force protected) ──
const crypto = require('crypto');

function timingSafeEqualStrings(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  const ba = Buffer.from(sa, 'utf8');
  const bb = Buffer.from(sb, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

function sha256Hex(value) {
  return crypto.createHash('sha256').update(String(value), 'utf8').digest('hex');
}

function routeSuccess(items) {
  return [items, []];
}

function routeError(message, code) {
  return [[], [{ json: { message, error: message, code } }]];
}

const headers = $input.first().json.headers ?? {};

function readAgencyAuthHeader(h) {
  const bag = h ?? {};
  for (const [key, value] of Object.entries(bag)) {
    if (key && key.toLowerCase() === 'x-agency-auth') {
      const v = String(value ?? '').trim();
      if (v) return v;
    }
  }
  return '';
}

function readCredential(item) {
  const header = readAgencyAuthHeader(item.headers ?? {});
  if (header) return header;
  const body = item.body ?? {};
  return String(body.pin ?? body.PIN ?? body.authKey ?? '').trim();
}

function stripSecrets(item) {
  const clean = { ...item };
  if (clean.body && typeof clean.body === 'object') {
    const b = { ...clean.body };
    delete b.pin;
    delete b.PIN;
    delete b.password;
    delete b.authKey;
    clean.body = b;
  }
  if (clean.headers && typeof clean.headers === 'object') {
    const h = { ...clean.headers };
    for (const key of Object.keys(h)) {
      if (key && key.toLowerCase() === 'x-agency-auth') delete h[key];
    }
    clean.headers = h;
  }
  return clean;
}

async function redisHeaders() {
  const token = String($env['REDIS_REST_TOKEN'] ?? '').trim();
  const h = {};
  if (token) h.Authorization = `Bearer ${token}`;
  return h;
}

function redisBase() {
  const base = String($env['REDIS_CONNECTION_URL'] ?? '').replace(/\/+$/, '');
  if (!base) {
    console.error('CRITICAL: REDIS_CONNECTION_URL missing from environment');
    return '';
  }
  return base;
}

async function redisIncrFail(key, windowSec) {
  const base = redisBase();
  const h = await redisHeaders();
  const enc = encodeURIComponent(key);
  const incrRes = await fetch(`${base}/incr/${enc}`, { method: 'POST', headers: h });
  if (!incrRes.ok) throw new Error(`REDIS_HTTP_FAIL: incr ${incrRes.status}`);
  const incrData = await incrRes.json();
  const count = Number(incrData.result ?? 0);
  if (count === 1) {
    await fetch(`${base}/expire/${enc}/${windowSec}`, { method: 'POST', headers: h });
  }
  return count;
}

async function redisIncrWindow(key, windowSec, max) {
  const count = await redisIncrFail(key, windowSec);
  if (count > max) {
    throw new Error(`RATE_LIMIT: ${count} requests in ${windowSec}s window (max ${max})`);
  }
  return count;
}

async function redisGet(key) {
  const base = redisBase();
  if (!base) return null;
  const h = await redisHeaders();
  const res = await fetch(`${base}/get/${encodeURIComponent(key)}`, { method: 'GET', headers: h });
  if (!res.ok) throw new Error(`REDIS_HTTP_FAIL: get ${res.status}`);
  const data = await res.json();
  return data.result;
}

async function redisDel(key) {
  const base = redisBase();
  const h = await redisHeaders();
  const res = await fetch(`${base}/del/${encodeURIComponent(key)}`, { method: 'POST', headers: h });
  if (!res.ok) throw new Error(`REDIS_HTTP_FAIL: del ${res.status}`);
}

function resolveExpectedHash() {
  const fromEnv = String($env['DASHBOARD_AUTH_KEY_SHA256'] ?? '').trim().toLowerCase();
  if (fromEnv) return fromEnv;
  const plain = String($env['DASHBOARD_AUTH_KEY'] ?? '').trim();
  if (!plain) return '';
  return sha256Hex(plain);
}

return (async () => {
  const rawItem = $input.first().json ?? {};
  const hdrs = rawItem.headers ?? {};
  const fwd = hdrs['x-forwarded-for'] ?? hdrs['X-Forwarded-For'] ?? '';
  const clientIp = String(fwd).split(',')[0].trim() || 'unknown';
  const clinicId = String($env['CLINIC_ID'] ?? 'temara').trim();
  const bruteKey = `authfail:dashboard:${clinicId}:${clientIp}`;

  let failCount = 0;
  let redis_outage_bypassed = false;
  try {
    failCount = Number(await redisGet(bruteKey) ?? 0);
  } catch (error) {
    console.error('Redis unreachable, failing open for auth:', error.message);
    redis_outage_bypassed = true;
    failCount = 0;
  }
  if (failCount >= 5) {
    return routeError('RATE_LIMIT: Brute-force protection — maximum 5 failed attempts in 15 minutes', 429);
  }

  const expectedHash = resolveExpectedHash();
  if (!expectedHash) {
    return routeError('AUTH_FAIL: DASHBOARD_AUTH_KEY is not configured', 401);
  }

  const credential = readCredential(rawItem);
  if (!credential) {
    await redisIncrFail(bruteKey, 900);
    return routeError('AUTH_FAIL: Invalid or missing credentials', 401);
  }

  const incomingHash = sha256Hex(credential);
  if (!timingSafeEqualStrings(incomingHash, expectedHash)) {
    await redisIncrFail(bruteKey, 900);
    return routeError('AUTH_FAIL: Invalid or missing credentials', 401);
  }

  await redisDel(bruteKey);
  try {
    await redisIncrWindow(`ratelimit:dashboard:${clientIp}`, 300, 30);
  } catch (error) {
    const msg = String(error?.message ?? error);
    if (msg.startsWith('RATE_LIMIT')) {
      return routeError(msg, 429);
    }
    throw error;
  }

  const CACHE_KEY = 'dashboard:kpi:payload';
  const cachedRaw = await redisGet(CACHE_KEY);
  if (cachedRaw) {
    try {
      const parsed = JSON.parse(cachedRaw);
      const cachedPayload = {
          _fromCache: true,
          _cacheAgeMs: 0,
          ...parsed,
        };
      if (redis_outage_bypassed) cachedPayload.redis_outage_bypassed = true;
      return routeSuccess([{ json: cachedPayload }]);
    } catch {
      // corrupt cache entry — fall through to fresh fetch
    }
  }

  const missPayload = { _fromCache: false };
  if (redis_outage_bypassed) missPayload.redis_outage_bypassed = true;
  return routeSuccess([{ json: missPayload }]);
})();

// ── Transform & Validate Google Sheets rows → typed KPI object ───────────────
//
// EXPECTED SHEET STRUCTURE (tab: Calculs, range A1:B30)
//   Row 1 : header  →  Metric | Valeur
//   Row 2 : patients_today  | <COUNTIFS formula result>
//   Row 3 : no_shows        | <COUNTIFS formula result>
//   Row 4 : revenue_today   | <SUMIFS formula result>
//   Row 5 : new_patients    | <COUNTIFS formula result>
//   Row 6 : accepted_plans  | <COUNTIF formula result>
//   Row 7 : pending_plans   | <COUNTIF formula result>
//   Row 8-18 : hour_08 through hour_18 (one per hour)
//
// SCHEMA: these are the only metric names the dashboard trusts.
// Any key not in this set is stripped from the output (defence-in-depth).

const NUMERIC_METRICS = new Set([
  'patients_today',
  'no_shows',
  'revenue_today',
  'new_patients',
  'accepted_plans',
  'pending_plans',
  'hour_08', 'hour_09', 'hour_10', 'hour_11', 'hour_12',
  'hour_13', 'hour_14', 'hour_15', 'hour_16', 'hour_17', 'hour_18',
]);

const STRING_METRICS = new Set([
  // reserved for future string metrics, e.g. next_patient_name
]);

const ALL_METRICS = new Set([...NUMERIC_METRICS, ...STRING_METRICS]);

// Safe parse: coerce to number, fallback to 0
function safeNum(v) {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return isFinite(n) ? n : 0;
}

const rows   = $input.all();
const result = {};
const errors = [];

for (const r of rows) {
  const raw = r.json ?? {};

  // Normalise column name capitalisation:
  // Sheets may return 'Metric'/'Valeur' or 'metric'/'valeur' depending on
  // sheet locale and n8n version.
  const metricKey = (
    raw['Metric'] ?? raw['metric'] ?? raw['METRIC'] ?? ''
  ).toString().trim();

  const rawValue = raw['Valeur'] ?? raw['valeur'] ?? raw['VALEUR'] ?? '';

  // Skip empty / header rows
  if (!metricKey || metricKey === 'Metric') continue;

  // Skip unknown metrics (schema guard)
  if (!ALL_METRICS.has(metricKey)) {
    errors.push(`Unknown metric ignored: '${metricKey}'`);
    continue;
  }

  // Type coercion
  if (NUMERIC_METRICS.has(metricKey)) {
    result[metricKey] = safeNum(rawValue);
  } else {
    result[metricKey] = String(rawValue).trim();
  }
}

// Fill any missing metrics with safe defaults so the dashboard
// always gets a complete object — never undefined keys.
for (const m of NUMERIC_METRICS) {
  if (!(m in result)) {
    result[m] = 0;
    errors.push(`Missing metric in Sheets: '${m}' — defaulted to 0`);
  }
}

// Schema validation summary
if (errors.length > 0) {
  console.warn('[Dashboard] Schema warnings:', errors.join(' | '));
}

// Timezone-aware timestamp (Africa/Casablanca)
const now = new Date();
const fetchedAt = now.toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

return (async () => {
// Update distributed cache (60s TTL)
const cachePayload = {
  ...result,
  last_updated:    fetchedAt,
  schema_warnings: errors,
};

async function redisSetEx(key, value, ttlSec) {
  const base = String($env['REDIS_CONNECTION_URL'] ?? '').replace(/\/+$/, '');
  const token = String($env['REDIS_REST_TOKEN'] ?? '').trim();
  if (!base) throw new Error('CRITICAL: REDIS_CONNECTION_URL missing from environment');
  const h = token ? { Authorization: `Bearer ${token}` } : {};
  const encKey = encodeURIComponent(key);
  const encVal = encodeURIComponent(value);
  const res = await fetch(`${base}/set/${encKey}/${encVal}?EX=${ttlSec}`, { method: 'POST', headers: h });
  if (!res.ok) throw new Error(`REDIS_HTTP_FAIL: set ${res.status}`);
}

await redisSetEx('dashboard:kpi:payload', JSON.stringify(cachePayload), 60);

return [{  json: {
    ...result,
    last_updated:    fetchedAt,
    _fromCache:      false,
    schema_warnings: errors,
  }
}];
})();

// ── Merge cache-hit path and fresh-fetch path ────────────────────────────────
// Both the cache-hit branch (true branch of IF) and the fresh-fetch branch
// (Transform & Validate) merge here before responding.
// This node just passes through — it exists to give the Merge a clear name.

const item = $input.first();
const payload = item.json;

// Add a trace/request ID for debugging
const traceId = `dash-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;

return [{
  json: {
    ok:          true,
    trace_id:    traceId,
    from_cache:  payload._fromCache ?? false,
    ...payload,
  }
}];

// ── Error Handler: build a structured error response ─────────────────────────
// This node fires when Auth + Rate Limit throws (AUTH_FAIL / RATE_LIMIT)
// OR when Get Dashboard KPIs / Transform nodes throw.
// It NEVER exposes internal stack traces to the client.

const err      = $input.first()?.json ?? {};
const errMsg   = (err.message ?? err.error ?? 'Internal error').toString();
const isAuth   = errMsg.startsWith('AUTH_FAIL');
const isRate   = errMsg.startsWith('RATE_LIMIT');

// Log full error internally
console.error('[Dashboard] Error:', errMsg);

const now = new Date().toLocaleString('fr-MA', {
  timeZone: 'Africa/Casablanca',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});

return [{
  json: {
    httpStatus: isAuth ? 401 : isRate ? 429 : 503,
    body: {
      ok:          false,
      error:       isAuth ? 'Unauthorized'
                 : isRate ? 'Too Many Requests'
                 : 'Service temporarily unavailable',
      message:     isAuth ? 'Invalid or missing credentials'
                 : isRate ? 'Brute-force protection triggered. Retry in 15 minutes.'
                 : 'Could not read data from Google Sheets. Retry in 30 seconds.',
      timestamp:   now,
      trace_id:    `err-${Date.now().toString(36)}`,
    }
  }
}];
